Rules.InvariantScript:
Set(varIsNewTicket, IsBlank(varCurrentTicket.ID));
// Reporting from an asset page already says which asset it is about, and editing
// an existing issue must not move it to another asset. Either way the asset is
// fixed and shown as text; the dropdown only appears when reporting from scratch.
Set(varTicketAsset, Coalesce(varCurrentTicket.Title, varCurrentAsset.Titel, ""));
Set(varTicketAssetFixed, !IsBlank(varTicketAsset))

Patch(
    Equipment_Tickets,
    // LookUp by ID, not the variable itself: a record carried in a global
    // variable loses its schema, and Patch rejects it as "a Record value,
    // but of a different schema".
    LookUp(Equipment_Tickets, ID = varCurrentTicket.ID),
    {
        ResolutionNotes: Trim(txtTkResolution.Text),
        ResolvedDate: Today(),
        // Save the status shown on screen as well, otherwise a
        // resolved issue keeps whatever status it had before.
        TicketStatus: { Value: drpTkStatus.Selected.Value },
        ResolvedBy: {
            '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
            Claims: "i:0#.f|membership|" & Lower(User().Email),
            DisplayName: User().FullName,
            Email: User().Email,
            Department: "",
            JobTitle: "",
            Picture: ""
        }
    }
);
If(
    IsEmpty(Errors(Equipment_Tickets)),
    Notify("Issue marked as resolved.", NotificationType.Success);
    Set(varCurrentTicket, Blank());
    Navigate(scr_Tickets, ScreenTransition.Fade),
    Notify(
        "Failed: " & Concat(Errors(Equipment_Tickets), Message, " | "),
        NotificationType.Error
    )
)

If(
    !IsBlank(lblTicketValidation.Text),
        Notify(lblTicketValidation.Text, NotificationType.Warning),
    // Patch gets a literal record in each branch. Handing it a record bound
    // with With() fails as "expecting a Record value, but of a different schema",
    // and putting the If around Defaults() and an existing record instead unions
    // two record types.
    If(
        varIsNewTicket,
            Patch(
                Equipment_Tickets,
                Defaults(Equipment_Tickets),
                {
                Title:           If(varTicketAssetFixed, varTicketAsset, drpTkAsset.Selected.Value),
                TypeMaintenance: { Value: drpTkType.Selected.Value },
                Severity:        { Value: drpTkSeverity.Selected.Value },
                TicketStatus:    { Value: drpTkStatus.Selected.Value },
                Description:     Trim(txtTkDescription.Text),
                ReportedDate:    Now(),
                ReportedBy: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                    Claims: "i:0#.f|membership|" & Lower(User().Email),
                    DisplayName: User().FullName,
                    Email: User().Email,
                    Department: "",
                    JobTitle: "",
                    Picture: ""
                }
                }
            ),
            Patch(
                Equipment_Tickets,
                // LookUp by ID, not the variable itself: a record carried in a global
                // variable loses its schema, and Patch rejects it as "a Record value,
                // but of a different schema".
                LookUp(Equipment_Tickets, ID = varCurrentTicket.ID),
                {
                Title:           If(varTicketAssetFixed, varTicketAsset, drpTkAsset.Selected.Value),
                TypeMaintenance: { Value: drpTkType.Selected.Value },
                Severity:        { Value: drpTkSeverity.Selected.Value },
                TicketStatus:    { Value: drpTkStatus.Selected.Value },
                // Who reported the issue and when are deliberately left alone
                // when an existing issue is edited. No trailing comma: a record
                // literal ending in one is a parse error, and a control whose
                // formula does not parse silently does nothing when tapped.
                Description:     Trim(txtTkDescription.Text)
                }
            )
    );
    If(
        IsEmpty(Errors(Equipment_Tickets)),
        Notify(
            If(varIsNewTicket, "Issue created.", "Issue updated."),
            NotificationType.Success
        );
        Set(varCurrentTicket, Blank());
        Navigate(scr_Tickets, ScreenTransition.Fade),
        Notify(
            "Save failed: " & Concat(Errors(Equipment_Tickets), Message, " | "),
            NotificationType.Error
        )
    )
)
